#' Interference Screening Testing
#'
#' 
#' @param data .
#' @param l .
#' @param g .
#' @param v .
#' @param tl .
#' @param cl .
#' @param im .
#' @param mu .
#' @param alpha .
#' @param wcv .
#' @param wsd .
#' @param wpd .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$text} \tab \tab \tab \tab \tab a preformatted \cr
#'   \code{results$da$t} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$is$t} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$c} \tab \tab \tab \tab \tab a preformatted \cr
#' }
#'
#' @export
InterferenceScreeningTesting <- function(
    data,
    l,
    g,
    v,
    tl = "Test",
    cl = "Control",
    im = "Vitamin C",
    mu = "nmol/L",
    alpha = 0.05,
    wcv = 5,
    wsd = 0.5,
    wpd = 10) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("InterferenceScreeningTesting requires jmvcore to be installed (restart may be required)")

    if ( ! missing(l)) l <- jmvcore::resolveQuo(jmvcore::enquo(l))
    if ( ! missing(g)) g <- jmvcore::resolveQuo(jmvcore::enquo(g))
    if ( ! missing(v)) v <- jmvcore::resolveQuo(jmvcore::enquo(v))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(l), l, NULL),
            `if`( ! missing(g), g, NULL),
            `if`( ! missing(v), v, NULL))


    options <- InterferenceScreeningTestingOptions$new(
        l = l,
        g = g,
        v = v,
        tl = tl,
        cl = cl,
        im = im,
        mu = mu,
        alpha = alpha,
        wcv = wcv,
        wsd = wsd,
        wpd = wpd)

    analysis <- InterferenceScreeningTestingClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

